import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../providers/app_provider.dart';

class ContactDetailScreen extends ConsumerWidget { final String contactId; const ContactDetailScreen({super.key, required this.contactId}); @override Widget build(BuildContext context, WidgetRef ref) { final d = ref.watch(appProvider); final c = d.contacts.firstWhere((x) => x.id == contactId); final tx = d.transactions.where((x) => x.contactId == contactId).toList()..sort((a,b) => b.date.compareTo(a.date)); final balance = c.type == 'customer' ? d.receivableFor(c.id) : d.payableFor(c.id); return Scaffold(appBar: AppBar(title: Text(c.name)), floatingActionButton: FloatingActionButton.extended(onPressed: () => _transaction(context, ref, c.id), icon: const Icon(Icons.add), label: const Text('Transaction')), body: ListView(padding: const EdgeInsets.all(16), children: [Card(child: Padding(padding: const EdgeInsets.all(18), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(c.type == 'customer' ? 'You should receive' : 'You should pay', style: Theme.of(context).textTheme.bodySmall), const SizedBox(height: 4), Text('PKR ${balance.toStringAsFixed(0)}', style: Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight: FontWeight.bold)), if (c.phone.isNotEmpty) Text(c.phone)])), const SizedBox(height: 16), Text('Ledger', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)), const SizedBox(height: 8), if (tx.isEmpty) const Card(child: Padding(padding: EdgeInsets.all(20), child: Text('No transactions yet'))) else ...tx.map((t) => Card(child: ListTile(leading: Icon(t.kind.contains('payment') ? Icons.payments_outlined : Icons.swap_horiz), title: Text(t.description.isEmpty ? t.kind.replaceAll('_', ' ') : t.description), subtitle: Text('${t.date.day}/${t.date.month}/${t.date.year} • ${t.paymentMethod}'), trailing: Text('PKR ${t.amount.toStringAsFixed(0)}'))))])); }
Future<void> _transaction(BuildContext context, WidgetRef ref, String id) async { final amount = TextEditingController(); final desc = TextEditingController(); String kind = 'credit'; await showDialog(context: context, builder: (_) => StatefulBuilder(builder: (context, setState) => AlertDialog(title: const Text('Add transaction'), content: Column(mainAxisSize: MainAxisSize.min, children: [DropdownButtonFormField<String>(value: kind, items: const [DropdownMenuItem(value: 'credit', child: Text('Credit / Sale')), DropdownMenuItem(value: 'payment_received', child: Text('Payment received')), DropdownMenuItem(value: 'purchase', child: Text('Purchase')), DropdownMenuItem(value: 'payment_given', child: Text('Payment given'))], onChanged: (v) => setState(() => kind = v!)), const SizedBox(height: 10), TextField(controller: amount, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Amount (PKR)')), const SizedBox(height: 10), TextField(controller: desc, decoration: const InputDecoration(labelText: 'Description'))]), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: () { final a = double.tryParse(amount.text); if (a != null && a > 0) { ref.read(appProvider.notifier).addTransaction(id, a, kind, desc.text); Navigator.pop(context); } }, child: const Text('Save'))]))); }
}
